/**
 * frontend/src/components/CameraRecognition.jsx
 * VERSION FUSIONNÉE - STABLE + ROBUSTE + DEBUG AVANCÉ
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const CAPTURE_INTERVAL = 500;
const CONFIDENCE_THRESHOLD = 0.5;

const COLORS = {
  primary: '#2563EB',
  success: '#16A34A',
  danger: '#DC2626',
  warning: '#D97706',
  gray: '#64748B',
  background: '#F8FAFC',
  text: '#0F172A',
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(true);
  const [loading, setLoading] = useState(false);

  const [status, setStatus] = useState('idle'); // idle | success | warning | error

  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhoto, setRegisteredPhoto] = useState(null);

  const [lastResult, setLastResult] = useState(null);
  const [lastTime, setLastTime] = useState(null);

  const [successCount, setSuccessCount] = useState(0);
  const [notRecognizedCount, setNotRecognizedCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [frameCount, setFrameCount] = useState(0);

  const [lastHttpCode, setLastHttpCode] = useState(null);
  const [lastBackendMsg, setLastBackendMsg] = useState(null);
  const [lastJsError, setLastJsError] = useState(null);

  const [errorMsg, setErrorMsg] = useState(null);

  // ================= AUDIO =================
  const playSound = useCallback((type) => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        osc.frequency.value = 900;
        gain.gain.value = 0.2;
      } else {
        osc.frequency.value = 300;
        gain.gain.value = 0.15;
      }

      osc.connect(gain).connect(ctx.destination);
      osc.start();
      setTimeout(() => osc.stop(), 200);
    } catch {}
  }, []);

  // ================= CAMERA =================
  const startCamera = async () => {
    try {
      setLoading(true);
      setErrorMsg(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user' },
        audio: false,
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          try {
            await videoRef.current.play();
          } catch {}

          setCameraActive(true);
          setAutoMode(true);
          setLoading(false);

          addNotification?.('📷 Caméra activée', 'success');
        };
      }
    } catch (err) {
      setLoading(false);
      setErrorMsg("Impossible d'accéder à la caméra");
      addNotification?.("❌ Caméra inaccessible", 'error');
    }
  };

  // ================= STOP =================
  const stopCamera = () => {
    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setAutoMode(false);
    setStatus('idle');
  };

  // ================= CAPTURE LOOP =================
  useEffect(() => {
    if (!cameraActive || !autoMode) {
      if (intervalRef.current) clearInterval(intervalRef.current);
      return;
    }

    intervalRef.current = setInterval(async () => {
      if (!videoRef.current || isProcessingRef.current) return;

      isProcessingRef.current = true;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);
        const payload = imageBase64.split(',')[1];

        setCapturedImage(imageBase64);
        setFrameCount(prev => prev + 1);

        const response = await attendanceAPI.recognize(payload);

        if (!response || !response.data) {
          setErrorMsg('Réponse backend vide ou invalide');
          setErrorCount(prev => prev + 1);
          return;
        }

        const data = response.data;
        const confidence = data.confidence || 0;

        setLastHttpCode(response.status || 200);
        setLastBackendMsg(data.message || 'OK');

        // ================= SUCCESS =================
        if (data.success && data.student) {
          setStatus('success');
          setSuccessCount(p => p + 1);
          setLastResult(data);
          setLastTime(new Date().toLocaleTimeString());
          setRegisteredPhoto(data.registered_photo_url || null);

          playSound('success');
          addNotification?.(`✅ ${data.student} reconnu`, 'success');
        }

        // ================= DETECTED BUT LOW CONF =================
        else if (confidence >= CONFIDENCE_THRESHOLD) {
          setStatus('warning');
          setNotRecognizedCount(p => p + 1);
          setErrorMsg(`Visage détecté mais confiance faible (${(confidence * 100).toFixed(1)}%)`);
        }

        // ================= NOT RECOGNIZED =================
        else {
          setStatus('error');
          setNotRecognizedCount(p => p + 1);
          setErrorMsg('Visage non reconnu');
        }

      } catch (err) {
        console.error('[ERROR]', err.response || err);

        const code = err.response?.status;
        const msg =
          err.response?.data?.message ||
          err.response?.data?.error ||
          err.message;

        setLastHttpCode(code || 'N/A');
        setLastBackendMsg(msg);
        setLastJsError(err.message);

        if (err.message?.toLowerCase().includes('cors') ||
            err.message?.toLowerCase().includes('network')) {
          setErrorMsg('❌ Erreur réseau ou CORS : vérifiez le backend');
        } else {
          setErrorMsg(`❌ Erreur API\nCode: ${code || '—'}\nMessage: ${msg}`);
        }

        setErrorCount(p => p + 1);
      } finally {
        isProcessingRef.current = false;
      }
    }, CAPTURE_INTERVAL);

    return () => clearInterval(intervalRef.current);
  }, [cameraActive, autoMode, addNotification, playSound]);

  // ================= MANUAL CAPTURE =================
  const manualCapture = async () => {
    if (!videoRef.current) return;

    try {
      setLoading(true);

      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);
      const payload = imageBase64.split(',')[1];

      const response = await attendanceAPI.recognize(payload);

      if (!response || !response.data) {
        setErrorMsg('Réponse backend invalide');
        return;
      }

      const data = response.data;

      if (data.success) {
        setStatus('success');
        setSuccessCount(p => p + 1);
        playSound('success');
      } else {
        setStatus('error');
        setNotRecognizedCount(p => p + 1);
      }

    } catch (err) {
      setErrorMsg('Erreur lors de la capture');
      setErrorCount(p => p + 1);
    } finally {
      setLoading(false);
    }
  };

  // ================= UI =================
  return (
    <div style={styles.container}>
      <h2>🎯 Reconnaissance Faciale</h2>

      <video
        ref={videoRef}
        autoPlay
        playsInline
        muted
        style={styles.video}
        aria-label="flux caméra"
      />

      <div style={styles.buttons}>
        {!cameraActive ? (
          <button onClick={startCamera} aria-label="démarrer caméra">
            📷 Démarrer
          </button>
        ) : (
          <>
            <button onClick={manualCapture}>📸 Capturer</button>
            <button onClick={() => setAutoMode(!autoMode)}>
              {autoMode ? '⏹ Stop Auto' : '▶ Start Auto'}
            </button>
            <button onClick={stopCamera}>🛑 Fermer</button>
          </>
        )}
      </div>

      {errorMsg && (
        <div style={styles.error}>{errorMsg}</div>
      )}

      <div style={styles.debug}>
        <p>Frames: {frameCount}</p>
        <p>Succès: {successCount}</p>
        <p>Non reconnus: {notRecognizedCount}</p>
        <p>Erreurs: {errorCount}</p>
        <p>HTTP: {lastHttpCode}</p>
        <p>Backend: {lastBackendMsg}</p>
        <p>JS: {lastJsError}</p>
      </div>
    </div>
  );
};

const styles = {
  container: { padding: 20 },
  video: { width: '100%', borderRadius: 10, background: '#000' },
  buttons: { display: 'flex', gap: 10, marginTop: 10 },
  error: { color: 'red', marginTop: 10 },
  debug: { marginTop: 20, fontSize: 12, color: '#666' }
};

export default CameraRecognition;
